-- QA hardening: default role templates should follow least privilege.
-- Owners can still delegate additional permissions with membership overrides.

with managed_positions as (
  select id from public.positions where is_system_template=true and code in (
    'MD_OWNER','CFO','FINANCE_MANAGER','SENIOR_ACCOUNTANT','ACCOUNTANT','ACCOUNTS_OFFICER','CASHIER',
    'PROJECT_DIRECTOR','SENIOR_PROJECT_COORDINATOR','PROJECT_COORDINATOR',
    'CONSTRUCTION_MANAGER','PROJECT_MANAGER','SITE_MANAGER','SITE_ENGINEER','SUPERVISOR','STOREKEEPER'
  )
)
delete from public.position_permissions pp using managed_positions mp where pp.position_id=mp.id;

