  ('SUPERVISOR','approvals.request','assigned_projects'),('SUPERVISOR','documents.upload','assigned_projects'),('SUPERVISOR','progress.update','assigned_projects'),('SUPERVISOR','projects.view','assigned_projects'),('SUPERVISOR','transactions.create','assigned_projects'),('SUPERVISOR','transactions.view','assigned_projects'),
