), resolved as (
  select p.id position_id, perm.id permission_id, d.scope::public.permission_scope scope
  from desired d
  join public.positions p on p.code=d.position_code and p.is_system_template=true
  join public.permissions perm on perm.code=d.permission_code
)
insert into public.position_permissions(position_id,permission_id,scope)
select position_id,permission_id,scope from resolved
on conflict(position_id,permission_id) do update set scope=excluded.scope;
